from pathlib import Path
import hashlib
import json
import re
import zipfile
from xml.etree import ElementTree as ET
from xml.sax.saxutils import escape, unescape

ROOT = Path(__file__).resolve().parent
inputs = ROOT / 'inputs'
before = {p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in inputs.iterdir() if p.is_file()}
rows = json.loads((inputs / 'intake.json').read_text(encoding='utf-8'))
text_pattern = re.compile(r'(<w:t\b[^>]*>)(.*?)(</w:t>)', re.S)

def fill(xml, values):
    matches = list(text_pattern.finditer(xml))
    texts = [unescape(m.group(2)) for m in matches]
    joined = ''.join(texts)
    offsets = []
    for i, text in enumerate(texts):
        offsets.extend((i, j) for j in range(len(text)))
    replacements = []
    for key, value in values.items():
        for m in re.finditer(re.escape('{{' + key + '}}'), joined):
            replacements.append((m.start(), m.end(), value))
    for start, end, value in sorted(replacements, reverse=True):
        first, left = offsets[start]
        last, right = offsets[end - 1]
        if first == last:
            texts[first] = texts[first][:left] + value + texts[first][right + 1:]
        else:
            texts[first] = texts[first][:left] + value
            for i in range(first + 1, last):
                texts[i] = ''
            texts[last] = texts[last][right + 1:]
    for m, text in reversed(list(zip(matches, texts))):
        xml = xml[:m.start(2)] + escape(text) + xml[m.end(2):]
    return xml

for row in rows:
    source = inputs / row['template']
    target = ROOT / 'output' / row['output']
    values = {key: row[key] for key in ('title_en', 'major')}
    values.update(author='Anonymous', student_id='Anonymous')
    with zipfile.ZipFile(source) as original, zipfile.ZipFile(target, 'w') as result:
        for entry in original.infolist():
            data = original.read(entry.filename)
            if entry.filename.endswith('.xml'):
                xml = data.decode('utf-8')
                if '<w:t' in xml:
                    xml = fill(xml, values)
                if entry.filename == '[Content_Types].xml':
                    xml = xml.replace('wordprocessingml.template.main+xml', 'wordprocessingml.document.main+xml')
                data = xml.encode('utf-8')
            result.writestr(entry, data)
    with zipfile.ZipFile(source) as original, zipfile.ZipFile(target) as result:
        assert result.testzip() is None
        assert original.namelist() == result.namelist()
        all_text = ''
        for name in result.namelist():
            data = result.read(name)
            for person in rows:
                assert person['author'].encode() not in data
                assert person['student_id'].encode() not in data
            if name.endswith('.xml'):
                tree = ET.fromstring(data)
                all_text += ''.join(tree.itertext())
                if name.startswith('word/'):
                    expected = fill(original.read(name).decode('utf-8'), values).encode('utf-8')
                    assert data == expected
            elif name != '[Content_Types].xml':
                assert data == original.read(name)
        assert '{{' not in all_text
        assert row['title_en'] in all_text and row['major'] in all_text
        assert 'Candidate: Anonymous' in all_text
        assert 'Registration: Anonymous' in all_text
        assert b'wordprocessingml.document.main+xml' in result.read('[Content_Types].xml')
        for name in original.namelist():
            if name not in ('word/document.xml', 'word/header1.xml', '[Content_Types].xml'):
                assert original.read(name) == result.read(name), name
    print(f'PASS: {target.name}: fields filled; anonymous; school parts preserved; ordinary DOCX')
assert before == {p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in inputs.iterdir() if p.is_file()}
print('PASS: all input files unchanged')
